package cn.zhuatech.siem.deep;import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="siem_log_sources",uniqueConstraints=@UniqueConstraint(columnNames={"organizationCode","sourceCode"})) class SecurityLogSource{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(nullable=false,length=40)String organizationCode;@Column(nullable=false,length=50)String sourceCode;@Column(nullable=false,length=120)String name;@Column(nullable=false,length=40)String sourceType;@Column(nullable=false,length=20)String status="DRAFT";LocalDateTime lastEventAt;LocalDateTime createdAt;protected SecurityLogSource(){}SecurityLogSource(String o,String c,String n,String t){organizationCode=o;sourceCode=c;name=n;sourceType=t;createdAt=LocalDateTime.now();}}
@Entity @Table(name="siem_detection_rules",uniqueConstraints=@UniqueConstraint(columnNames={"organizationCode","ruleCode"})) class DetectionRule{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(nullable=false,length=40)String organizationCode;@Column(nullable=false,length=50)String ruleCode;@Column(nullable=false,length=120)String name;@Column(nullable=false,length=50)String eventType;int minimumSeverity;@Column(nullable=false,length=20)String incidentSeverity;@Column(nullable=false,length=20)String status="ACTIVE";protected DetectionRule(){}DetectionRule(String o,String c,String n,String e,int m,String s){organizationCode=o;ruleCode=c;name=n;eventType=e;minimumSeverity=m;incidentSeverity=s;}}
@Entity @Table(name="siem_security_events",uniqueConstraints=@UniqueConstraint(columnNames="eventId")) class SecurityEvent{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Column(nullable=false,length=70)String eventId;@Column(nullable=false)Long sourceId;@Column(nullable=false,length=50)String eventType;int severityScore;@Column(nullable=false,length=100)String principal;@Column(nullable=false,length=100)String asset;@Column(nullable=false,length=500)String summary;LocalDateTime occurredAt;protected SecurityEvent(){}SecurityEvent(String e,Long s,String t,int score,String p,String a,String sum,LocalDateTime at){eventId=e;sourceId=s;eventType=t;severityScore=score;principal=p;asset=a;summary=sum;occurredAt=at;}}
@Entity @Table(name="siem_incidents",uniqueConstraints=@UniqueConstraint(columnNames="incidentNo")) class SecurityIncident{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Version long version;@Column(nullable=false)Long eventId;@Column(nullable=false)Long ruleId;@Column(nullable=false,length=50)String incidentNo;@Column(nullable=false,length=20)String severity;@Column(nullable=false,length=25)String status="OPEN";@Column(length=50)String assignee;@Column(length=500)String investigationNote;@Column(length=64)String evidenceHash;@Column(length=500)String responseAction;LocalDateTime createdAt;LocalDateTime closedAt;protected SecurityIncident(){}SecurityIncident(Long e,Long r,String n,String s){eventId=e;ruleId=r;incidentNo=n;severity=s;createdAt=LocalDateTime.now();}}
